WHERE {
  GRAPH <hydroturtle/lamah_ce> {
    ?frostDay a sosa:Observation ;
      sosa:observedProperty <http://vocabs.lter-europe.net/EnvThes/30212> ;
      sosa:madeBySensor <Bangs_gauging_station> ;
      sosa:resultTime ?date ;
      sosa:hasSimpleResult ?result .
    FILTER(?result < 0)
    FILTER(?date >= "2010-01-01"^^xsd:date && ?date <= "2020-12-31"^^xsd:date)
  }
}
